mod audio; mod game; mod video;
use game::Game;
fn main(){let mut captures=vec![];for (source,handler,terrain,death_state) in [(30,0x8d76,1,3),(47,0xa36d,0,4),(48,0xa36d,0,4)]{let mut g=Game::new(false).unwrap();g.memory.fill(0);g.memory[0x300..0x500].fill(terrain*0x55);g.memory[0x720]=source;g.memory[0x710]=128;g.memory[0x560]=80;g.memory[0x530]=1;g.memory[0x5b0]=160;g.memory[0x570]=100;g.memory[0x6c0]=10;let mut samples=vec![];for tick in 0..200 {g.memory[0x1a]=tick as u8;g.memory[0x721]=7;g.memory[0x711]=g.memory[0x710];g.memory[0x6f1]=g.memory[0x6f0];g.memory[0x561]=g.memory[0x560];g.memory[0x701]=g.memory[0x700];g.actor_call(handler,0).unwrap();let triggered=g.memory[0x520]&127==death_state;samples.push(serde_json::json!({"tick":tick,"triggered":triggered,"sprite":g.memory[0x500],"x":i16::from_le_bytes([g.memory[0x710],g.memory[0x6f0]])as f32+g.memory[0x5c0]as f32/256.,"y":i16::from_le_bytes([g.memory[0x560],g.memory[0x700]])as f32+g.memory[0x580]as f32/256.}));if triggered{break;}}captures.push(serde_json::json!({"source":source,"terrain":terrain,"samples":samples}));}println!("{}",serde_json::to_string(&captures).unwrap());}
